draw:
var nF = p.nfilm, nS = p.nsub;
var flipTop = nF > 1.0;
var flipBot = nS > nF;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var yTop = H * 0.40, yBot = H * 0.68;
var x0 = W * 0.10, x1 = W * 0.92;

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(x0, yTop); ctx.lineTo(x1, yTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, yBot); ctx.lineTo(x1, yBot); ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
for (var s = 0; s < 26; s++) {
  var xs = x0 + (x1 - x0) * s / 25;
  ctx.beginPath(); ctx.moveTo(xs, yBot); ctx.lineTo(xs + 7, yBot + 9); ctx.stroke();
}

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("air, n = 1.00", x0 + 4, yTop - 8);
ctx.fillText("film, n = " + nF.toFixed(2), x0 + 4, (yTop + yBot) / 2 + 4);
ctx.fillText("substrate, n = " + nS.toFixed(2), x0 + 4, yBot + 22);

var hitA = W * 0.34, hitB = W * 0.58;
var dx = (hitB - hitA);

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.6;
ctx.beginPath(); ctx.moveTo(hitA - dx, yTop - (yTop - 12)); ctx.lineTo(hitA, yTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(hitA, yTop); ctx.lineTo(hitA + dx * 0.55, 12); ctx.stroke();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.6;
ctx.beginPath();
ctx.moveTo(hitA, yTop); ctx.lineTo(hitB, yBot); ctx.lineTo(hitB + (hitB - hitA), yTop);
ctx.lineTo(hitB + (hitB - hitA) + dx * 0.55, 12);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("ray 1", hitA + dx * 0.30, 26);
ctx.fillText("ray 2", hitB + (hitB - hitA) + dx * 0.34, 26);
ctx.textAlign = "left";
ctx.fillText("in", Math.max(2, hitA - dx + 4), 26);

ctx.fillStyle = C.accent;
ctx.textAlign = "center";
ctx.fillText("extra path 2t, optical path 2nt", (hitA + hitB) / 2 + 20, yBot + 22);

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(W * 0.05, yTop); ctx.lineTo(W * 0.05, yBot); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("t", W * 0.05 + 4, (yTop + yBot) / 2 + 4);

var mark = function (x, y, on) {
  ctx.fillStyle = on ? C.accent : C.faint;
  ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText(on ? "flip" : "no flip", x, y - 10);
};
mark(hitA, yTop, flipTop);
mark(hitB, yBot, flipBot);

var n = (flipTop ? 1 : 0) + (flipBot ? 1 : 0);
var cond = (n % 2 === 1) ? "bright when 2nt = (m + 1/2) lambda" : "bright when 2nt = m lambda";
out.note = n + " flip(s): " + cond;

var nTop = 1.0;
var nF = p.nfilm, nS = p.nsub, th = p.thick;
var flipTop = nF > nTop ? 1 : 0;
var flipBot = nS > nF ? 1 : 0;
var net = (flipTop + flipBot) % 2;

var padL = 44, padR = 14, padT = 16, padB = 30;
var gx0 = padL, gx1 = W - padR, gy0 = padT, gy1 = H - padB;
var lam0 = 400, lam1 = 700;
var X = function (lam) { return gx0 + (lam - lam0) / (lam1 - lam0) * (gx1 - gx0); };
var Y = function (v) { return gy1 - v * (gy1 - gy0); };

var refl = function (lam) {
  var delta = 2 * Math.PI * (2 * nF * th) / lam + (net ? Math.PI : 0);
  var c = Math.cos(delta / 2);
  return c * c;
};

ctx.lineWidth = 1;
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.lineTo(gx1, gy1);
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
for (var lam = 400; lam <= 700; lam += 50) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(X(lam), gy1); ctx.lineTo(X(lam), gy1 + 4); ctx.stroke();
  ctx.fillText(String(lam), X(lam), gy1 + 17);
}
ctx.fillText("wavelength in vacuum (nm)", (gx0 + gx1) / 2, gy1 + 29);
ctx.textAlign = "right";
ctx.fillText("1", gx0 - 6, gy0 + 5);
ctx.fillText("0", gx0 - 6, gy1 + 4);
ctx.save();
ctx.translate(14, (gy0 + gy1) / 2);
ctx.rotate(-Math.PI / 2);
ctx.textAlign = "center";
ctx.fillText("reflected", 0, 0);
ctx.restore();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 300; i++) {
  var L = lam0 + (lam1 - lam0) * i / 300;
  var px = X(L), py = Y(refl(L));
  if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
}
ctx.stroke();

var scan = lam0 + (lam1 - lam0) * (0.5 - 0.5 * Math.cos(t * 0.7));
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(scan), gy0); ctx.lineTo(X(scan), gy1); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(scan), Y(refl(scan)), 4, 0, Math.PI * 2); ctx.fill();

var best = lam0, bestV = -1, dark = 0, darkV = 2;
for (var k = 0; k <= 300; k++) {
  var Lk = lam0 + (lam1 - lam0) * k / 300;
  var v = refl(Lk);
  if (v > bestV) { bestV = v; best = Lk; }
  if (v < darkV) { darkV = v; dark = Lk; }
}
out.note = "flips: " + (flipTop + flipBot) + "  |  2nt = " + (2 * nF * th).toFixed(0) +
  " nm  |  brightest near " + best.toFixed(0) + " nm, weakest near " + dark.toFixed(0) + " nm";

var R = p.radius, lam = p.lambda * 1e-9, ng = p.ngap;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var mMax = 14;
var rMax = Math.sqrt(mMax * lam * R / ng);
var cx = W * 0.5, cy = H * 0.52;
var Rpx = Math.min(W, H) * 0.42;
var S = Rpx / rMax;

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(cx, cy, Rpx, 0, Math.PI * 2); ctx.stroke();

var highlight = 1 + (Math.floor(t / 1.2) % 6);

for (var m = 1; m <= mMax; m++) {
  var r = Math.sqrt(m * lam * R / ng) * S;
  if (r > Rpx) break;
  ctx.strokeStyle = (m === highlight) ? C.accent : C.ink;
  ctx.lineWidth = (m === highlight) ? 3 : 1.6;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
}

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "center";
ctx.fillText("dark centre, m = 0", cx, cy + Rpx + 18);

var rh = Math.sqrt(highlight * lam * R / ng);
var rhpx = rh * S;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + rhpx, cy); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("m = " + highlight, cx + rhpx * 0.35, cy - 6);

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("dark rings, 2 n t = m lambda", 6, 14);

out.note = "ring m = " + highlight + " has radius " + (rh * 1000).toFixed(3) +
  " mm  |  gap there t = " + (rh * rh / (2 * R) * 1e9).toFixed(0) + " nm";
